code_sketch:
const esc = (s: string): string =>
  s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]!));

export function artistView(a: Artist): string {
  const items = a.albums.map((al) => `<li>${esc(al.title)}</li>`).join("");
  return `<h1>${esc(a.name)}</h1><ul>${items}</ul>`;
}

